BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path=public,extensions;
SELECT no_plan();
CREATE TEMP TABLE temp_test_state(name text PRIMARY KEY,value jsonb);
INSERT INTO temp_test_state VALUES
 ('alice',public.temporary_start(repeat('a',64),'demo','alice')),
 ('visitor',public.temporary_start(repeat('b',64),'demo','alice')),
 ('guest',public.temporary_start(repeat('c',64),'guest',NULL));
SELECT is((SELECT value->>'kind' FROM temp_test_state WHERE name='guest'),'guest','guest starts successfully');
SELECT is(public.temporary_list(repeat('c',64),1),'[]'::jsonb,'guest workspace begins empty');
SELECT is((SELECT value->>'workspaceId' FROM temp_test_state WHERE name='alice')=(SELECT value->>'workspaceId' FROM temp_test_state WHERE name='visitor'),false,'two Alice visitors get separate workspaces');
SELECT is((SELECT bool_and(NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'temporary_%'),true,'all public temporary wrappers restrict execution to service role');
SELECT is(has_schema_privilege('anon','temporary_private','USAGE'),false,'anonymous cannot use private schema');
SELECT is(has_schema_privilege('authenticated','temporary_private','USAGE'),false,'users cannot use private schema');
SELECT is(has_schema_privilege('service_role','temporary_private','USAGE'),false,'service cannot query private tables outside wrappers');
SELECT is((SELECT bool_and(c.relrowsecurity) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='temporary_private' AND c.relkind='r'),true,'private tables have RLS defense in depth');
SELECT throws_ok($$SELECT public.temporary_start('guessed','guest',NULL)$$,'P0001','VALIDATION_ERROR','invalid hash rejected');
SELECT throws_ok($$SELECT public.temporary_start(repeat('d',64),'guest','alice')$$,'P0001','VALIDATION_ERROR','guest cannot acquire a persona');
SELECT throws_ok($$SELECT public.temporary_start(repeat('d',64),'demo','administrator')$$,'P0001','VALIDATION_ERROR','demo persona allowlist');
INSERT INTO temp_test_state VALUES ('doc',public.temporary_create(repeat('a',64),1,'{"title":"Private Alice","content":"<p>First</p>"}'));
SELECT throws_ok(format('SELECT public.temporary_get(%L,1,%L)',repeat('b',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc')),'P0001','NOT_FOUND','another visitor cannot guess document id');
SELECT throws_ok(format('SELECT public.temporary_get(%L,1,%L)',repeat('0',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc')),'P0001','SESSION_EXPIRED','guessed token fails closed');
SELECT throws_ok(format('SELECT public.temporary_get(%L,2,%L)',repeat('a',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc')),'P0001','DEMO_RESET','stale generation rejected');
SELECT throws_ok($$SELECT public.temporary_list(repeat('a',64),NULL)$$,'P0001','VALIDATION_ERROR','missing generation never authorizes a store operation');
SELECT is((public.temporary_session(repeat('a',64))->>'token_hash') IS NULL,true,'session DTO contains no credential');
INSERT INTO temp_test_state VALUES ('share',public.temporary_grant_share(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),'{"persona":"bob"}','view'));
SELECT is(public.temporary_persona(repeat('a',64),1,'bob')->>'persona','bob','persona changes persist in database');
SELECT is(public.temporary_get(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'))->'permissions'->>'role','viewer','viewer can read shared document');
SELECT throws_ok(format('SELECT public.temporary_update(%L,1,%L,%L::jsonb)',repeat('a',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc'),'{"title":"Spoof"}'),'P0001','FORBIDDEN','viewer cannot edit');
SELECT throws_ok(format('SELECT public.temporary_remove(%L,1,%L)',repeat('a',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc')),'P0001','FORBIDDEN','viewer cannot delete');
SELECT throws_ok(format('SELECT public.temporary_restore(%L,1,%L,%L)',repeat('a',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc'),gen_random_uuid()),'P0001','FORBIDDEN','viewer cannot restore');
SELECT throws_ok(format('SELECT public.temporary_add_attachment(%L,1,%L,%L::jsonb)',repeat('a',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc'),'{"filename":"a.txt","mimeType":"text/plain","sizeBytes":1,"url":"/attachments/abc"}'),'P0001','FORBIDDEN','viewer cannot upload');
SELECT is(jsonb_array_length(public.temporary_heartbeat(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),'{"active":true,"cursorOffset":2}')),1,'viewer can send presence');
SELECT is(public.temporary_heartbeat(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),'{"active":true}')->0->>'userId','bob','presence identity comes from database persona');
SELECT is(jsonb_array_length(public.temporary_heartbeat(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),'{"active":false}')),0,'inactive presence removes own entry');
SELECT public.temporary_persona(repeat('a',64),1,'alice');
SELECT public.temporary_grant_share(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),'{"persona":"bob"}','edit');
SELECT public.temporary_persona(repeat('a',64),1,'bob');
SELECT is(public.temporary_update(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),'{"title":"Edited","content":"<p>Second</p>","createVersion":true}')->>'title','Edited','editor can update with history');
SELECT throws_ok(format('SELECT public.temporary_grant_share(%L,1,%L,%L::jsonb,%L)',repeat('a',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc'),'{"persona":"charlie"}','edit'),'P0001','FORBIDDEN','editor cannot manage shares');
SELECT is(public.temporary_restore(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),(SELECT id FROM temporary_private.history WHERE document_id=(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc') LIMIT 1))->>'content','<p>First</p>','editor can restore retained history');
SELECT is(public.temporary_add_attachment(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),'{"filename":"a.txt","mimeType":"text/plain","sizeBytes":1,"url":"/attachments/abc"}')->>'filename','a.txt','editor can upload inert metadata');
SELECT public.temporary_persona(repeat('a',64),1,'alice');
SELECT public.temporary_revoke_share(repeat('a',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='doc'),(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='share'));
SELECT public.temporary_persona(repeat('a',64),1,'bob');
SELECT throws_ok(format('SELECT public.temporary_get(%L,1,%L)',repeat('a',64),(SELECT value->>'id' FROM temp_test_state WHERE name='doc')),'P0001','NOT_FOUND','revocation applies immediately to existing credential');
SELECT throws_ok($$SELECT public.temporary_persona(repeat('c',64),1,'alice')$$,'P0001','FORBIDDEN','guest cannot switch persona');
INSERT INTO temp_test_state VALUES ('guest-doc',public.temporary_create(repeat('c',64),1,'{"title":"Guest","content":""}'));
SELECT throws_ok(format('SELECT public.temporary_grant_share(%L,1,%L,%L::jsonb,%L)',repeat('c',64),(SELECT value->>'id' FROM temp_test_state WHERE name='guest-doc'),'{"persona":"alice"}','edit'),'P0001','FORBIDDEN','guest cannot share');
SELECT throws_ok(format('SELECT public.temporary_update(%L,1,%L,jsonb_build_object(''content'',repeat(''x'',1048577)))',repeat('c',64),(SELECT value->>'id' FROM temp_test_state WHERE name='guest-doc')),'P0001','QUOTA_EXCEEDED','one MiB document cap is byte based');
SELECT throws_ok(format('SELECT public.temporary_update(%L,1,%L,jsonb_build_object(''content'',repeat(''😀'',262145)))',repeat('c',64),(SELECT value->>'id' FROM temp_test_state WHERE name='guest-doc')),'P0001','QUOTA_EXCEEDED','HTML cap measures UTF8 bytes rather than character count');
DO $$ DECLARE i integer; d uuid:=(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='guest-doc'); BEGIN
 FOR i IN 1..55 LOOP PERFORM public.temporary_update(repeat('c',64),1,d,jsonb_build_object('content',i::text,'createVersion',true)); END LOOP;
 FOR i IN 2..20 LOOP PERFORM public.temporary_create(repeat('c',64),1,'{"title":"Quota","content":""}'); END LOOP;
END $$;
SELECT is(jsonb_array_length(public.temporary_get(repeat('c',64),1,(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='guest-doc'))->'history'),50,'history pruned to fifty latest revisions');
SELECT is(jsonb_array_length(public.temporary_list(repeat('c',64),1)),20,'twenty documents admitted');
SELECT throws_ok($$SELECT public.temporary_create(repeat('c',64),1,'{"title":"Overflow","content":""}')$$,'P0001','QUOTA_EXCEEDED','twenty first document denied');
INSERT INTO temp_test_state VALUES ('bytes-session',public.temporary_start(repeat('e',64),'guest',NULL));
INSERT INTO temp_test_state VALUES ('bytes-doc',public.temporary_create(repeat('e',64),1,jsonb_build_object('title','Bytes','content',repeat('x',1048576))));
DO $$ DECLARE i integer; d uuid:=(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='bytes-doc'); BEGIN
 FOR i IN 1..24 LOOP PERFORM public.temporary_update(repeat('e',64),1,d,jsonb_build_object('content',repeat('x',1048576),'createVersion',true)); END LOOP;
END $$;
SELECT throws_ok(format('SELECT public.temporary_update(%L,1,%L,jsonb_build_object(''content'',repeat(''x'',1048576),''createVersion'',true))',repeat('e',64),(SELECT value->>'id' FROM temp_test_state WHERE name='bytes-doc')),'P0001','QUOTA_EXCEEDED','combined live plus history cap rejects twenty sixth MiB');
SELECT is((SELECT count(*)::integer FROM temporary_private.history WHERE document_id=(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='bytes-doc')),24,'failed quota write rolls back its history insertion');
UPDATE temporary_private.workspaces SET expires_at=clock_timestamp() WHERE id=(SELECT (value->>'workspaceId')::uuid FROM temp_test_state WHERE name='guest');
SELECT throws_ok($$SELECT public.temporary_list(repeat('c',64),1)$$,'P0001','SESSION_EXPIRED','fixed expiry enforced without cleanup');
SELECT public.temporary_end(repeat('c',64));
SELECT is((SELECT count(*)::integer FROM temporary_private.sessions WHERE token_hash=repeat('c',64)),0,'end cascades session deletion');
SELECT is((SELECT count(*)::integer FROM temporary_private.documents WHERE workspace_id=(SELECT (value->>'workspaceId')::uuid FROM temp_test_state WHERE name='guest')),0,'end cascades documents');
SELECT is((SELECT count(*)::integer FROM temporary_private.history WHERE document_id=(SELECT (value->>'id')::uuid FROM temp_test_state WHERE name='guest-doc')),0,'end cascades history');
SELECT * FROM finish();
ROLLBACK;
